/* Offline diagnostic contract v0.1. Raw evidence remains immutable on import. */
names.diagnostic=['诊断与评分','Diagnosis & scoring'];
const dimensions=[['access','可访问与可读取','Access & readability',25],['entity','品牌实体与事实完整','Entity & facts',20],['questions','用户问题覆盖与回答质量','Question coverage',20],['trust','证据支持与可信度','Evidence & trust',15],['structure','内容结构与机器可读性','Structure & readability',10],['maintenance','跨页面一致性与维护','Consistency & maintenance',10]];
const stateLabels={pass:['通过','Pass'],partial:['部分满足','Partial'],fail:['未满足','Fail'],unknown:['证据不足','Unknown'],not_applicable:['不适用','N/A']};
const findingLabels={observed_fact:['已观察事实','Observed fact'],supported_gap:['证据支持的缺口','Supported gap'],hypothesis:['待验证假设','Hypothesis'],unknown:['无法判断','Unknown']};
let diagnosticTab='summary',bundle=null,comparison=null;
const label=(map,k)=>map[k]?.[en?1:0]||k;
function demoBundle(){
 const evidence=[{evidence_id:'E-PAGE-01',source_type:'page_snapshot',provided_at:'2026-10-17T14:00:00Z',url:'https://aster.example/products/refill',hash:'demo-only-no-real-hash',locator:'main > section.specifications',excerpt:'Synthetic page: refill tablets, 12-pack. Usage conditions are not supplied.',integrity:'complete',entry:'Synthetic HTML fixture'}, {evidence_id:'E-FACT-01',source_type:'brand_fact',provided_at:'2026-10-17T14:00:00Z',url:'https://aster.example/about',hash:'demo-only-no-real-hash',locator:'Brand identity',excerpt:'Aster Home is a fictional brand used only for interface demonstration.',integrity:'complete',entry:'Synthetic fact fixture'}];
 const statuses=['pass','partial','fail','unknown','pass','partial'];
 const rules=dimensions.map((d,i)=>({rule_id:'R-'+d[0],dimension:d[0],weight:d[3],status:statuses[i],partial_credit:.5,reason:['示例页面正文可读取。','示例包装规格明确，适用条件仍不完整。','示例页面未回答冷水使用条件这一决策问题。','没有独立来源支持，尚不能判断。','示例内容有清晰标题层级。','示例版本日期存在，跨页面一致性仍需核对。'][i],evidence_ids:i===3?[]:[i===1?'E-FACT-01':'E-PAGE-01'],target_page:'https://aster.example/products/refill',rubric:'pass = 1; partial = 0.5 (predefined); fail = 0',verification:'保留完整页面快照，核对字段、适用范围及原文。',version:'v0.1',na_reason:''}));
 return {schema_version:'v0.1',demo:true,run_manifest:{run_id:'DEMO-2026-10-17',brand:'Aster Home',domains:['aster.example'],market:'us',language:'en',mode:'full',rule_version:'v0.1',parser_version:'v0.1',judge_version:'manual-v1',question_set_version:'q1',page_set_version:'pages1',configuration:'demo-frozen-1',sampled_at:'2026-10-17T14:00:00Z',page_weighting:'代表页样本；本例仅一个产品页',planned:4,attempted:4},rules,evidence,answers:[{evidence_id:'E-ANSWER-01',question_id:'Q-01',question:'Which refill tablets work in cold water?',question_version:1,question_type:'discovery',platform:'Illustrative Search',entry:'Web · demo',market:'us',language:'en',status:'success',raw_answer:'Synthetic answer: Aster Home is one option. Check the usage conditions before choosing.',mention:true,recommendation:null,citation_supported:true,citation_complete:true,citation_type:'web_panel',citations:[{url:'https://aster.example/products/refill'}],truncated:false,cached:false,region:'US',network_evidence:'synthetic fixture',collected_at:'2026-10-17T14:00:00Z'}, {evidence_id:'E-ANSWER-02',question_id:'Q-02',question:'Compare refill formats',question_version:1,question_type:'discovery',platform:'Illustrative Search',entry:'Web · demo',market:'us',language:'en',status:'success',raw_answer:'Synthetic answer: compare packaging and usage instructions.',mention:false,recommendation:false,citation_supported:true,citation_complete:true,citation_type:'web_panel',citations:[],collected_at:'2026-10-17T14:00:00Z'}, {evidence_id:'E-ANSWER-03',question_id:'Q-03',question:'What does Aster Home sell?',question_version:1,question_type:'brand',platform:'Illustrative Search',entry:'Web · demo',market:'us',language:'en',status:'success',raw_answer:'Synthetic branded question; excluded from discovery metrics.',mention:true,recommendation:null,citation_supported:false,citation_complete:false,citations:[],collected_at:'2026-10-17T14:00:00Z'}, {evidence_id:'E-ANSWER-04',question_id:'Q-01',question:'Which refill tablets work in cold water?',question_version:1,question_type:'discovery',platform:'Illustrative Search',entry:'Web · demo',market:'us',language:'en',status:'failed',raw_answer:'',mention:null,recommendation:null,citation_supported:false,citation_complete:false,citations:[],collected_at:'2026-10-17T14:00:00Z'}],findings:[{finding_id:'F-01',scope:'产品页',status:'fail',finding_type:'supported_gap',priority:'P1',question_ids:['Q-01'],evidence_ids:['E-PAGE-01'],rule_ids:['R-questions'],target_pages:['https://aster.example/products/refill'],observed_gap:'示例页面没有说明冷水使用条件。',alternative_explanations:'来源权威、索引、地区和采样波动均可能影响回答；本缺口不能证明推荐缺席的原因。',recommended_action:'在使用说明段落补充已核实的水温、用量与限制条件。',owner:'内容负责人',effort_band:'小',verification:'核对批准事实与页面快照；冻结问题和入口后重新采样。',priority_reason:'有示例页面证据，涉及主要购买问题。',candidate:'[待补事实] 适用水温：___；用量：___；限制条件：___。',publication_status:'unpublished'}]};
}
function activeBundle(){return bundle||demoBundle()}
function scoreRules(rules){const applicable=rules.filter(r=>r.status!=='not_applicable');const A=applicable.reduce((s,r)=>s+r.weight,0),U=applicable.filter(r=>r.status==='unknown').reduce((s,r)=>s+r.weight,0),P=applicable.reduce((s,r)=>s+r.weight*(r.status==='pass'?1:r.status==='partial'?r.partial_credit:0),0);return{applicable_weight:A,unknown_weight:U,earned:P,lower:A?100*P/A:null,upper:A?100*(P+U)/A:null,coverage:A?(A-U)/A:null,total:A&&U===0?100*P/A:null}}
const num=n=>n===null?'—':Number(n.toFixed(1)).toString();
function diagnosticMetrics(b){const groups=new Map();for(const a of b.answers){const key=JSON.stringify([a.platform,a.entry,a.market,a.language,a.question_type]);if(!groups.has(key))groups.set(key,{platform:a.platform,entry:a.entry,market:a.market,language:a.language,question_type:a.question_type,answers:[]});groups.get(key).answers.push(a)}return [...groups.values()].map(g=>{const valid=g.answers.filter(a=>a.status==='success'&&!a.truncated&&!a.cached),known=valid.filter(a=>typeof a.mention==='boolean'),rec=valid.filter(a=>typeof a.recommendation==='boolean'),cap=valid.filter(a=>a.citation_supported===true&&a.citation_complete===true&&['api_native','web_panel'].includes(a.citation_type));const own=a=>(a.citations||[]).some(c=>{try{const h=new URL(c.url).hostname;return b.run_manifest.domains.some(d=>h===d||h.endsWith('.'+d))}catch{return false}});return{...g,valid:valid.length,failed:g.answers.filter(a=>a.status==='failed').length,unusable:g.answers.length-valid.length,mention:{numerator:known.filter(a=>a.mention).length,denominator:known.length},recommendation:{numerator:rec.filter(a=>a.recommendation).length,denominator:rec.length},owned_citation:{numerator:cap.filter(own).length,denominator:cap.length},capture:{numerator:cap.length,denominator:valid.length}}})}
function ratio(x){return x.denominator?`${pct(x.numerator/x.denominator)} <small>${x.numerator}/${x.denominator}</small>`:`— <small>unknown · 0/0</small>`}
function diagTag(status){return `<span class="tag ${status==='fail'?'diag-fail':status==='unknown'?'warn':status==='pass'?'badge':''}">${esc(label(stateLabels,status))}</span>`}
function diagnosticPage(){const b=activeBundle(),s=scoreRules(b.rules),tabs=[['summary','一页结论','Summary'],['performance','平台表现','Performance'],['readiness','六维诊断','Readiness'],['coverage','问题与来源','Questions & sources'],['actions','页面行动包','Page actions'],['evidence','证据附录','Evidence'],['retest','复测与口径','Retest']];return `<div class="diag-hero"><div><div class="diag-eyebrow">EVIDENCE → DIAGNOSIS → ACTION</div><h2>${t('每个结论，都有来处。','Every conclusion has a source.')}</h2><p>${t('先确认观察，再判断缺口，最后安排修改与复测。','Observe first. Diagnose gaps. Plan changes and retests.')}</p><span class="tag">${b.demo?'SYNTHETIC DEMO':b.generator?t('后台自动诊断','Backend diagnosis'):t('本次会话导入','Session import')}</span> <span class="tag">${esc(b.run_manifest.run_id)}</span></div><div class="diag-hero-actions">${diagBackend()?`<button class="primary" onclick="diagnosticGenerateModal()">＋ ${t('从官网生成诊断','Diagnose a website')}</button>`:''}<button class="${diagBackend()?'':'primary'}" onclick="diagnosticImport()">＋ ${t('导入诊断证据包','Import evidence bundle')}</button><button onclick="downloadJSON(diagnosticTemplate(),'run-bundle-template.json')">↓ ${t('下载空白模板','Blank template')}</button>${bundle?`<button onclick="bundle=null;comparison=null;render()">${t('返回示例','Use demo')}</button>`:''}</div></div><div class="notice">${b.demo?t('以下内容全部是虚构示例，用于演示计分和证据链，未运行真实诊断或平台采样。','All content below is synthetic. No real diagnosis or platform sampling was run.'):b.generator?t('由后台抓取官网后按固定规则自动判定，结果保存在后台。“证据不足”的规则未计分，需补充证据或人工复核。','Generated by the backend from fetched pages with fixed rules and stored there. Unknown rules are unscored until reviewed.'):t('导入材料仅保存在当前浏览器会话内存中，刷新后清除；请及时导出报告。不上传到公共网站。','Imported material stays in this browser session memory and clears on refresh. Export your report before leaving. No upload is made.')}</div>${bundle?'':diagnosticHistory()}<div class="tabs diag-tabs">${tabs.map(([id,zh,english])=>`<button class="${diagnosticTab===id?'selected':''}" onclick="diagnosticTab='${id}';render()">${t(zh,english)}</button>`).join('')}</div>${({summary:()=>diagnosticSummary(b,s),performance:()=>diagnosticPerformance(b),readiness:()=>diagnosticReadiness(b),coverage:()=>diagnosticCoverage(b),actions:()=>diagnosticActions(b),evidence:()=>diagnosticEvidence(b),retest:()=>diagnosticRetest(b)})[diagnosticTab]()}<section class="card diag-export"><div><h2>${t('同一份数据，多种交付','One source of truth, multiple exports')}</h2><p class="subtitle">${t('JSON、HTML 和 Markdown 共享计分结果；PDF 通过 HTML 的浏览器打印生成。','JSON, HTML and Markdown share the same scores. Print the HTML report to PDF.')}</p></div><div class="actions"><button onclick="diagnosticExport('json')">JSON</button><button onclick="diagnosticExport('html')">HTML / PDF</button><button onclick="diagnosticExport('md')">Markdown</button></div></section>${bundle?diagnosticHistory():''}`}
function diagnosticSummary(b,s){const m=b.run_manifest;return `<div class="diag-summary"><section class="card diag-score"><div class="diag-eyebrow">${t('代表页样本 · 准备度','REPRESENTATIVE PAGES · READINESS')}</div><div class="diag-score-number">${s.total!==null?num(s.total):`${num(s.lower)}<span>–</span>${num(s.upper)}`}</div><h2>${s.total!==null?t('正式准备度得分','Readiness score'):s.applicable_weight?t('正式总分待补证据','Final score pending evidence'):t('无法评分','Unable to score')}</h2><p class="subtitle">${t('规则分数的数学边界；不是概率置信区间。','Mathematical score bounds, not a confidence interval.')}</p><div class="diag-coverage"><div class="platform-info"><span>${t('证据覆盖','Evidence coverage')}</span><b>${pct(s.coverage)}</b></div><div class="bar"><i style="width:${(s.coverage||0)*100}%"></i></div><p class="subtitle">A ${s.applicable_weight} · P ${s.earned} · U ${s.unknown_weight}</p></div></section><section class="card"><div class="card-head"><h2>${t('本次范围与方法','Scope & method')}</h2><span class="tag">${esc(m.rule_version)} · ${t('暂定规则','Proposed rules')}</span></div><div class="kv"><span>${t('品牌 / 市场','Brand / market')}</span><b>${esc(m.brand)} · ${esc(m.market)}</b><span>${t('材料语言 / 模式','Language / mode')}</span><span>${esc(m.language)} · ${esc(m.mode)}</span><span>${t('计划 / 尝试 / 导入记录','Planned / attempted / imported')}</span><span>${m.planned??'unknown'} / ${m.attempted??'unknown'} / ${b.answers.length}</span><span>${t('页面集合与权重','Page set & weights')}</span><span>${esc(m.page_weighting||t('未声明','Not declared'))}</span><span>${t('时间 / 题集版本','Time / question set')}</span><span>${esc(m.sampled_at||'unknown')} · ${esc(m.question_set_version)}</span></div><p class="subtitle">${t('中文界面不代表中国市场。权重是 v0.1 产品规则，不是平台排名权重。','Interface language does not define the market. v0.1 weights are product rules, not platform ranking factors.')}</p></section></div><div class="grid"><section class="card"><div class="card-head"><h2>${t('六维准备度','Six readiness dimensions')}</h2><button class="small" onclick="diagnosticTab='readiness';render()">${t('查看规则','View rules')} →</button></div>${dimensions.map(d=>{const x=scoreRules(b.rules.filter(r=>r.dimension===d[0]));return `<div class="platform-row"><div class="platform-info"><span>${en?d[2]:d[1]} <span class="muted">${d[3]}%</span></span><b>${x.applicable_weight?x.total!==null?num(x.total):num(x.lower)+'–'+num(x.upper):'N/A'}</b></div><div class="diag-range"><i style="width:${x.lower||0}%"></i><em style="left:${x.lower||0}%;width:${(x.upper||0)-(x.lower||0)}%"></em></div></div>`}).join('')}</section><section class="card"><h2>${t('优先行动与关键阻断','Priority actions & blockers')}</h2>${b.findings.length?b.findings.slice(0,3).map(f=>`<div class="diag-finding"><span class="tag ${f.priority==='P0'?'diag-fail':'warn'}">${esc(f.priority)}</span> <span class="muted small">${esc(label(findingLabels,f.finding_type))}</span><p>${esc(f.observed_gap)}</p><button class="link" onclick="diagnosticTab='actions';render()">${esc(f.recommended_action)} →</button></div>`).join(''):`<p class="muted">${t('没有已导入诊断；不自动推断缺口。','No findings imported; gaps are not inferred automatically.')}</p>`}<p class="subtitle">${t('假设单独待验证；不预测未经验证的曝光提升。','Hypotheses require testing. No unverified visibility lift is predicted.')}</p></section></div>`}
function diagnosticPerformance(b){const ms=diagnosticMetrics(b);return `<section class="card"><div class="card-head"><h2>${t('按实际平台入口与题型分开统计','Metrics by actual entry point and question type')}</h2><span class="tag">${t('样本表现 ≠ 全体流量','Sample results ≠ all traffic')}</span></div>${table([t('平台 / 入口 / 市场','Platform / entry / market'),t('题型','Question type'),t('有效 / 记录','Valid / records'),t('提及','Mention'),t('明确推荐','Explicit recommendation'),t('自有域原生引用','Owned native citation'),t('引用捕获覆盖','Citation capture')],ms.map(g=>`<tr><td>${esc(g.platform)}<div class="row-meta">${esc(g.entry)} · ${esc(g.market)} · ${esc(g.language)}</div></td><td>${esc(g.question_type)}</td><td>${g.valid}/${g.answers.length}<div class="row-meta">${t('失败','Failed')}: ${g.failed} · ${t('不可用','Unusable')}: ${g.unusable}</div></td><td>${ratio(g.mention)}</td><td>${ratio(g.recommendation)}</td><td>${ratio(g.owned_citation)}</td><td>${ratio(g.capture)}</td></tr>`).join(''))}<p class="subtitle">${t('discovery 为中性发现题，brand 为品牌题，comparison 为指定比较题，各自统计。截断、缓存重复与失败不当成未提及。未提供明确判定的推荐为 unknown。首次出现位置不等于推荐排名。','Discovery, brand and comparison questions are separate. Failed, truncated and duplicate cached samples are excluded. Unjudged recommendations are unknown. First appearance is not recommendation rank.')}</p></section><section class="card" style="margin-top:20px"><h2>${t('指标 → 问题 → 原始回答','Metric → question → original answer')}</h2>${b.answers.map(a=>`<details class="diag-detail"><summary><span class="tag">${esc(a.evidence_id)}</span> ${esc(a.question)} <span class="muted small">${esc(a.platform)} · ${esc(a.status)}</span></summary><div class="kv"><span>${t('采样条件','Conditions')}</span><span>${esc(a.entry)} · ${esc(a.market)} · ${esc(a.language)} · v${a.question_version} · ${esc(a.collected_at||'unknown')}</span><span>${t('引用类型 / 完整性','Citation type / integrity')}</span><span>${esc(a.citation_type||'unknown')} / ${a.citation_complete===true?'complete':'unknown'}</span><span>${t('联网证据','Network evidence')}</span><span>${esc(a.network_evidence||'unknown')}</span></div><pre class="evidence">${esc(a.raw_answer)||t('没有原文','No original answer')}</pre>${(a.citations||[]).map(c=>`<p>${safeURL(c.url)?`<a target="_blank" rel="noopener noreferrer" href="${esc(c.url)}">${esc(c.url)}</a>`:esc(c.url)}</p>`).join('')}</details>`).join('')||`<p class="muted">${t('尚无回答；实际曝光指标为 unknown。','No answers; actual visibility is unknown.')}</p>`}</section>`}
function evidenceLinks(b,ids){return ids.map(id=>`<button class="small" onclick="diagnosticEvidenceDrawer(decodeURIComponent('${enc(id)}'))">${esc(id)} ↗</button>`).join(' ')||'<span class="muted">unknown</span>'}
function diagnosticReadiness(b){return `<div class="notice">${t('unknown 保留在适用分母，N/A 须说明理由。没有 FAQPage、llms.txt、固定字数或放开训练 bot 不统一扣分。','Unknown stays in the applicable denominator. N/A requires a reason. FAQPage, llms.txt, word counts and training bot access are not universal scoring requirements.')}</div>${dimensions.map(d=>{const rules=b.rules.filter(r=>r.dimension===d[0]);return `<section class="card" style="margin-bottom:16px"><div class="card-head"><h2>${en?d[2]:d[1]}</h2><span class="tag">${t('设计权重','Design weight')} ${d[3]} / 100</span></div>${rules.map(r=>`<details class="diag-detail"><summary>${diagTag(r.status)} <b>${esc(r.rule_id)}${r.title?' '+esc(r.title):''}</b> · ${esc(r.reason)}</summary><div class="kv"><span>${t('页面','Page')}</span><span>${esc(r.target_page||'unknown')}</span><span>${t('适用权重 / 计分','Weight / rubric')}</span><span>${r.weight} · ${esc(r.rubric)} · ${esc(r.version)}</span><span>${t('N/A 理由','N/A reason')}</span><span>${esc(r.na_reason||'—')}</span><span>${t('复核方法','Verification')}</span><span>${esc(r.verification)}</span></div><div class="actions">${evidenceLinks(b,r.evidence_ids)}</div></details>`).join('')||`<p class="muted">${t('未导入此维度的规则。','No rules imported for this dimension.')}</p>`}</section>`}).join('')}`}
function diagnosticActions(b){return b.findings.map(f=>`<section class="card" style="margin-bottom:18px"><div class="card-head"><h2>${esc(f.finding_id)} · ${esc(f.observed_gap)}</h2><span class="tag ${f.priority==='P0'?'diag-fail':'warn'}">${esc(f.priority)}</span></div><span class="tag">${esc(label(findingLabels,f.finding_type))}</span> ${diagTag(f.status)}<div class="kv"><span>${t('问题 / 规则','Questions / rules')}</span><span>${esc(f.question_ids.join(', '))} · ${esc(f.rule_ids.join(', '))}</span><span>${t('目标页面 / 位置','Target pages / scope')}</span><span>${esc(f.target_pages.join(', '))} · ${esc(f.scope)}</span><span>${t('建议修改','Action')}</span><b>${esc(f.recommended_action)}</b><span>${t('责任 / 成本','Owner / effort')}</span><span>${esc(f.owner)} · ${esc(f.effort_band)}</span><span>${t('优先级依据','Priority reason')}</span><span>${esc(f.priority_reason)}</span><span>${t('替代解释','Alternative explanations')}</span><span>${esc(f.alternative_explanations||'unknown')}</span><span>${t('复测方法','Verification')}</span><span>${esc(f.verification)}</span></div><div class="actions">${evidenceLinks(b,f.evidence_ids)}</div><details class="diag-detail"><summary>${t('查看候选改稿 · 未发布','Candidate change · Unpublished')}</summary><pre class="evidence">${esc(f.candidate||t('尚无候选改稿，请先补充事实。','No candidate yet. Supply verified facts first.'))}</pre><p class="subtitle">${t('候选内容不表示已实施；人工回执与线上核对需另行记录。','A candidate is not an implemented change. Record implementation receipts and live verification separately.')}</p></details></section>`).join('')||empty(t('暂无诊断行动','No actions yet'),t('导入包含证据、规则与目标页面的 findings。','Import findings linked to evidence, rules and target pages.'),'')}
function diagnosticEvidence(b){return `<section class="card"><div class="card-head"><h2>${t('原始证据索引','Raw evidence index')}</h2><span class="tag">${b.evidence.length} ${t('条页面/事实证据','page / fact records')}</span></div>${table(['ID',t('类型 / 时间','Type / time'),t('地址 / 片段','Object / locator'),t('完整性','Integrity'),t('查看','Inspect')],b.evidence.map(e=>`<tr><td>${esc(e.evidence_id)}</td><td>${esc(e.source_type)}<div class="row-meta">${esc(e.provided_at)}</div></td><td>${esc(e.url)}<div class="row-meta">${esc(e.locator)}</div></td><td>${esc(e.integrity)}</td><td>${evidenceLinks(b,[e.evidence_id])}</td></tr>`).join(''))}<p class="subtitle">${t('hash 与完整性是导入方声明，未自动核验远程对象。原始记录不在界面中覆盖编辑；解析和评分保留版本。','Hashes and integrity are supplied declarations, not remote verification. Raw records are not overwritten in the interface; parsing and scoring retain versions.')}</p></section>`}
function diagnosticEvidenceDrawer(id){const b=activeBundle(),e=b.evidence.find(e=>e.evidence_id===id)||b.answers.find(a=>a.evidence_id===id);if(!e)return;drawer(head(esc(id))+`<div class="evidence">${esc(e.excerpt||e.raw_answer||'')}</div><pre class="evidence">${esc(JSON.stringify(e,null,2))}</pre><button onclick="downloadJSON(activeBundle().evidence.concat(activeBundle().answers).find(e=>e.evidence_id===decodeURIComponent('${enc(id)}')),'evidence.json')">↓ ${t('下载原始记录','Download raw record')}</button>`)}
function compareBundles(a,b){const keys=['brand','market','language','rule_version','parser_version','judge_version','question_set_version','page_set_version','configuration'];const differences=keys.filter(k=>JSON.stringify(a.run_manifest[k])!==JSON.stringify(b.run_manifest[k]));const signature=x=>JSON.stringify(x.answers.map(r=>[r.question_id,r.question,r.question_version,r.question_type,r.platform,r.entry,r.market,r.language,r.region??null,r.citation_supported,r.citation_type??null]).sort((a,b)=>JSON.stringify(a).localeCompare(JSON.stringify(b))));if(signature(a)!==signature(b))differences.push('actual sampling conditions / question and entry set');const rs=x=>JSON.stringify(x.rules.map(r=>[r.rule_id,r.dimension,r.weight,r.rubric,r.partial_credit,r.target_page,r.version,r.na_reason]).sort((a,b)=>String(a[0]).localeCompare(String(b[0]))));if(rs(a)!==rs(b))differences.push('actual rules / page set');if([...a.answers,...b.answers].some(r=>r.cached||r.truncated))differences.push('cached / truncated samples');return{comparable:!differences.length,differences,baseline:scoreRules(a.rules),current:scoreRules(b.rules)}}
function diagnosticRetest(b){const m=b.run_manifest;return `<section class="card"><div class="card-head"><h2>${t('冻结配置，先检查可比性','Freeze configuration, check comparability first')}</h2><button onclick="diagnosticImport(true)">${t('导入基线进行比较','Import baseline')}</button></div><div class="kv">${['rule_version','parser_version','judge_version','question_set_version','page_set_version','configuration'].map(k=>`<span>${k}</span><span>${esc(m[k])}</span>`).join('')}</div><p>${t('复测需保留问题原文与版本、平台入口、地区、语言、引用能力、页面集合与权重。离线重新计分不当作新采样。','Freeze prompts, versions, entries, regions, languages, citation capabilities and page weights. Offline rescoring is not new sampling.')}</p>${comparison?`<div class="notice"><b>${comparison.comparable?t('配置可比','Configuration comparable'):t('不可合并为统一提升数字','No unified lift can be calculated')}</b></div>${comparison.differences.map(k=>`<p class="error">• ${esc(k)}</p>`).join('')}${comparison.comparable?`<p>${t('准备度边界','Readiness bounds')}: ${num(comparison.baseline.lower)}–${num(comparison.baseline.upper)} → ${num(comparison.current.lower)}–${num(comparison.current.upper)}</p><p class="subtitle">${t('配置一致仍不证明因果效果；需确认新采样与实施记录。','Matching configuration does not establish causality. Verify fresh collection and implementation records.')}</p>`:''}`:`<p class="muted">${t('尚未导入基线，不展示提升比例或趋势。','No baseline imported. No lift or trend is shown.')}</p>`}</section>`}
function validateBundle(b){const fail=s=>{throw Error(s)};if(!b||b.schema_version!=='v0.1')fail('schema_version must be v0.1');for(const k of ['rules','evidence','answers','findings'])if(!Array.isArray(b[k])||b[k].length>5000)fail(k+' must be an array (max 5000)');if(typeof b.demo!=='boolean')fail('demo must be boolean');const m=b.run_manifest;if(!m)fail('run_manifest required');if(!['page','answers','full','retest'].includes(m.mode))fail('mode: page / answers / full / retest');for(const k of ['run_id','brand','market','language','mode','rule_version','parser_version','judge_version','question_set_version','page_set_version','configuration','page_weighting'])if(typeof m[k]!=='string'||!m[k].trim())fail('run_manifest.'+k+' required');if(!Array.isArray(m.domains)||m.domains.some(d=>typeof d!=='string'||!/^([a-z0-9-]+\.)+[a-z0-9-]+$/i.test(d)))fail('domains: bare hostnames required');for(const k of ['planned','attempted'])if(m[k]!=null&&(!Number.isInteger(m[k])||m[k]<0))fail(k+' must be a nonnegative integer or null');if(m.planned!=null&&m.attempted>m.planned)fail('attempted exceeds planned');const ids=new Set();for(const e of [...b.evidence,...b.answers]){if(typeof e.evidence_id!=='string'||!e.evidence_id||ids.has(e.evidence_id))fail('evidence_id missing or duplicate');ids.add(e.evidence_id)}for(const e of b.evidence)for(const k of ['source_type','provided_at','url','hash','locator','excerpt','integrity','entry'])if(typeof e[k]!=='string'||!e[k].trim())fail(e.evidence_id+': '+k+' required');const ruleIds=new Set();const totals={};for(const r of b.rules){if(typeof r.rule_id!=='string'||!r.rule_id||ruleIds.has(r.rule_id))fail('rule_id missing or duplicate');ruleIds.add(r.rule_id);if(!dimensions.some(d=>d[0]===r.dimension))fail('Unknown dimension');if(!Number.isFinite(r.weight)||r.weight<=0)fail('Rule weight must be positive');totals[r.dimension]=(totals[r.dimension]||0)+r.weight;if(!stateLabels[r.status])fail('Invalid rule status');if(r.status==='partial'&&(!Number.isFinite(r.partial_credit)||r.partial_credit<=0||r.partial_credit>=1))fail('partial_credit must be predefined between 0 and 1');for(const k of ['reason','rubric','verification','version','target_page'])if(typeof r[k]!=='string'||!r[k].trim())fail(r.rule_id+': '+k+' required');if(!Array.isArray(r.evidence_ids)||r.evidence_ids.some(id=>!ids.has(id)))fail('Unknown evidence reference');if(['pass','partial','fail'].includes(r.status)&&!r.evidence_ids.length)fail('Judged rules need evidence');if(r.status==='not_applicable'&&!r.na_reason?.trim())fail('N/A requires na_reason')};for(const d of dimensions)if(Math.abs((totals[d[0]]||0)-d[3])>.0001)fail(d[0]+': weights must total '+d[3]+'; use unknown for missing rules');const questions=new Set([...(b.questions||[]).map(q=>q.question_id),...b.answers.map(a=>a.question_id)]);for(const a of b.answers){for(const k of ['question_id','question','platform','entry','market','language','collected_at'])if(typeof a[k]!=='string'||!a[k].trim())fail(a.evidence_id+': '+k+' required');if(!Number.isInteger(a.question_version)||a.question_version<1)fail('question_version required');if(!['discovery','brand','comparison'].includes(a.question_type))fail('question_type required');if(!['success','failed','no_answer','unknown'].includes(a.status))fail('Invalid answer status');if(a.status==='success'&&(typeof a.raw_answer!=='string'||!a.raw_answer.trim()))fail('Successful answer needs raw_answer');for(const k of ['mention','recommendation'])if(a[k]!==null&&typeof a[k]!=='boolean')fail(k+' must be boolean or null');if(!Array.isArray(a.citations)||a.citations.some(c=>!safeURL(c.url)))fail('citations must contain HTTP(S) URLs');if(a.citation_complete&&!a.citation_supported)fail('Complete citations require citation support');if(isNaN(Date.parse(a.collected_at)))fail('Invalid collected_at')};const fs=new Set();for(const f of b.findings){if(!f.finding_id||fs.has(f.finding_id))fail('finding_id missing or duplicate');fs.add(f.finding_id);if(!findingLabels[f.finding_type]||!stateLabels[f.status]||!['P0','P1','P2','待验证'].includes(f.priority))fail('Invalid finding type, status or priority');for(const k of ['scope','observed_gap','alternative_explanations','recommended_action','owner','effort_band','verification','priority_reason'])if(typeof f[k]!=='string'||!f[k].trim())fail(f.finding_id+': '+k+' required');for(const [key,set] of [['evidence_ids',ids],['rule_ids',ruleIds],['question_ids',questions]])if(!Array.isArray(f[key])||f[key].some(id=>!set.has(id)))fail('Invalid '+key);if(!Array.isArray(f.target_pages)||!f.target_pages.length)fail('target_pages required');if(['observed_fact','supported_gap'].includes(f.finding_type)&&!f.evidence_ids.length)fail('Facts and gaps need evidence');if(f.finding_type==='hypothesis'&&f.priority!=='待验证')fail('Hypotheses must use priority 待验证');if(f.priority==='P0'&&(!f.evidence_ids.length||f.finding_type!=='supported_gap'&&f.finding_type!=='observed_fact'))fail('P0 requires verified evidence');if(f.publication_status&&f.publication_status!=='unpublished')fail('Candidates must be unpublished')};return b}
function diagnosticTemplate(){return{schema_version:'v0.1',demo:false,run_manifest:{run_id:'',brand:'',domains:[],market:'',language:'',mode:'page',rule_version:'v0.1',parser_version:'manual-v1',judge_version:'manual-v1',question_set_version:'q1',page_set_version:'pages1',configuration:'',sampled_at:'',planned:null,attempted:null,page_weighting:'代表页样本；请填写页面类型和权重'},questions:[],rules:dimensions.map(d=>({rule_id:'R-'+d[0],dimension:d[0],weight:d[3],status:'unknown',partial_credit:.5,evidence_ids:[],target_page:'请填写具体页面 URL',reason:'尚未采集证据',rubric:'pass=1; partial=0.5; fail=0；请在判定前明确业务条件',verification:'请填写复核方法',version:'v0.1',na_reason:''})),evidence:[],answers:[],findings:[]}}
function diagnosticImport(baseline=false){modal(head(baseline?t('导入复测基线','Import baseline'):t('导入离线诊断证据包','Import offline evidence bundle'))+`<p>${t('支持 v0.1 JSON：run_manifest、rules、evidence、answers、findings。先验收字段和证据引用，再按规则重算。不会调用采集器或模型补全判断。','v0.1 JSON: run_manifest, rules, evidence, answers, findings. Validate references, then recompute scores. No collector or model fills missing judgments.')}</p><div class="actions"><button onclick="downloadJSON(diagnosticTemplate(),'run-bundle-template.json')">${t('空白模板','Blank template')}</button><button onclick="downloadJSON(demoBundle(),'SYNTHETIC-example-bundle.json')">${t('完整示例','Full example')}</button><input type="file" id="bundleFile" accept=".json" aria-label="JSON evidence bundle"></div>${area(t('JSON 证据包','JSON evidence bundle'),'bundleText')}<div class="actions" style="margin-top:16px"><button class="primary" onclick="acceptDiagnostic(${baseline})">${t('校验并载入','Validate & load')}</button></div><p id="bundleError" class="error" role="alert"></p>`);$('#bundleFile').onchange=async e=>{const f=e.target.files[0];if(f){if(f.size>8*1024*1024){$('#bundleError').textContent='Max 8 MB';return}$('#bundleText').value=await f.text()}}}
function acceptDiagnostic(baseline){try{const text=$('#bundleText').value;if(text.length>8*1024*1024)throw Error('Max 8 MB');const b=validateBundle(JSON.parse(text));if(baseline)comparison=compareBundles(b,activeBundle());else{bundle=structuredClone(b);comparison=null}closeOverlay();diagnosticTab=baseline?'retest':'summary';if(page!=='diagnostic')go('diagnostic');render();toast(t('证据包已验收，计分已重算','Bundle validated, scores recomputed'))}catch(e){$('#bundleError').textContent=e.message}}
function diagnosticReport(){const b=structuredClone(activeBundle());return{...b,computed_at:now(),scores:scoreRules(b.rules),dimension_scores:dimensions.map(d=>({dimension:d[0],...scoreRules(b.rules.filter(r=>r.dimension===d[0]))})),performance:diagnosticMetrics(b).map(({answers,...g})=>g),comparability:comparison,limitations:['v0.1 proposed weights; not platform ranking weights','No automated sampling or causal lift inference','Imported hashes and judgments are declarations, not independently verified','Candidate changes are unpublished']}}
function saveText(text,name,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function diagnosticExport(type){const r=diagnosticReport(),stem=r.demo?'SYNTHETIC-DEMO-report':'geo-report';if(type==='json'){downloadJSON(r,stem+'.json');return}const s=r.scores,lines=[`# Signal GEO · ${r.demo?'SYNTHETIC DEMO':'诊断报告'}`,`Run: ${r.run_manifest.run_id}`,`品牌: ${r.run_manifest.brand} · 市场: ${r.run_manifest.market} · 语言: ${r.run_manifest.language}`,`准备度: ${s.total!==null?num(s.total):num(s.lower)+'–'+num(s.upper)+'（正式总分待补证据）'}；证据覆盖 ${pct(s.coverage)}`,`规则边界，非概率区间；v0.1 暂定规则，不代表平台排名权重。`,`## 范围与方法`,JSON.stringify(r.run_manifest,null,2),`## 平台表现（含分子 / 分母）`,JSON.stringify(r.performance,null,2),`## 六维规则与证据`,...r.rules.map(x=>`${x.rule_id} · ${x.dimension} · ${x.status} · weight ${x.weight}\n${x.reason}\nEvidence: ${x.evidence_ids.join(', ')}\nRubric: ${x.rubric}\nVerify: ${x.verification}`),`## 页面行动包（候选未发布）`,...r.findings.map(f=>JSON.stringify(f,null,2)),`## 复测与可比性`,JSON.stringify(r.comparability),`## 原始回答`,...r.answers.map(a=>JSON.stringify(a,null,2)),`## 页面与事实证据`,...r.evidence.map(e=>JSON.stringify(e,null,2)),`## 限制`,...r.limitations];if(type==='md')saveText(lines.join('\n\n'),stem+'.md','text/markdown;charset=utf-8');else{const content=lines.map(l=>l.startsWith('## ')?`<h2>${esc(l.slice(3))}</h2>`:l.startsWith('# ')?`<h1>${esc(l.slice(2))}</h1>`:`<pre>${esc(l)}</pre>`).join('');saveText(`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>Signal GEO Report</title><style>body{font:14px system-ui;max-width:1000px;margin:40px auto;color:#252a38;padding:24px}h1,h2{color:#6554d9}pre{font:13px system-ui;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8;border-bottom:1px solid #ddd;padding:16px 0}@media print{button{display:none}h2{break-after:avoid}}</style><button onclick="window.print()">打印 / 保存 PDF</button>${content}</html>`,stem+'.html','text/html;charset=utf-8')}}
function diagnosticCoverage(b){const qs=new Map((b.questions||[]).map(q=>[q.question_id,q.question]));for(const a of b.answers)qs.set(a.question_id,a.question);const sources=new Map();for(const a of b.answers.filter(a=>a.status==='success'&&!a.truncated&&!a.cached))for(const c of a.citations||[]){const x=sources.get(c.url)||{url:c.url,ids:[],types:new Set(),domain:new URL(c.url).hostname};if(!x.ids.includes(a.evidence_id))x.ids.push(a.evidence_id);x.types.add(a.citation_type||'unknown');sources.set(c.url,x)}return `<section class="card"><h2>${t('消费者问题 → 所需信息 → 页面缺口','Consumer question → required information → page gap')}</h2>${table([t('问题','Question'),t('目标页面 / 已知缺口','Target pages / known gaps'),t('判断 / 证据','Judgment / evidence')],[...qs].map(([id,q])=>{const fs=b.findings.filter(f=>f.question_ids.includes(id));return `<tr><td>${esc(id)}<p>${esc(q)}</p></td><td>${fs.length?fs.map(f=>`${esc(f.target_pages.join(', '))}<p>${esc(f.observed_gap)}</p>`).join(''):t('未提供页面覆盖判断','Page coverage not supplied')}</td><td>${fs.length?fs.map(f=>`${diagTag(f.status)} ${evidenceLinks(b,f.evidence_ids)}`).join('<br>'):'unknown'}</td></tr>`}).join(''))}<p class="subtitle">${t('没有发现缺口记录，不等于页面已完整覆盖。需按问题核对必需事实。','No gap record does not establish complete coverage. Verify required decision facts per question.')}</p></section><section class="card" style="margin-top:20px"><h2>${t('实际引用来源与可控程度','Observed citation sources & control')}</h2>${table([t('来源 URL / 域名','Source URL / domain'),t('引用类型','Citation type'),t('品牌控制','Brand control'),t('回答证据','Answer evidence')],[...sources.values()].map(x=>`<tr><td><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.url)}</a><div class="row-meta">${esc(x.domain)}</div></td><td>${esc([...x.types].join(', '))}</td><td>${b.run_manifest.domains.some(d=>x.domain===d||x.domain.endsWith('.'+d))?t('自有页面 · 可修改','Owned page · Editable'):t('外部来源 · 合作关系未知','External · Relationship unknown')}</td><td>${evidenceLinks(b,x.ids)}</td></tr>`).join(''))}<p class="subtitle">${t('正文 URL、搜索结果、原生引用分开标注。来源相似不证明推荐机制；页面抓取成功也不等于平台引用。','Text URLs, search results and native citations are distinct. Similar sources do not establish ranking causality. A fetched page is not a platform citation.')}</p></section><section class="card" style="margin-top:20px"><h2>${t('数据质量与可核查事实','Data quality & verifiable facts')}</h2><div class="kv">${['success','no_answer','failed','unknown'].map(s=>`<span>${s}</span><span>${b.answers.filter(a=>a.status===s).length}</span>`).join('')}<span>${t('截断 / 缓存标记','Truncated / cached')}</span><span>${b.answers.filter(a=>a.truncated).length} / ${b.answers.filter(a=>a.cached).length}</span><span>${t('事实正确率 / 竞品差距','Fact accuracy / competitor gap')}</span><span>unknown · ${t('未导入逐条核查与配对判定','No item-level checks or paired judgments supplied')}</span></div></section>`}
const baseRender=render;
render=function(){baseRender();if(page!=='diagnostic')return;const b=activeBundle(),actions=document.querySelector('.page-head .actions');actions.innerHTML=`<button onclick="diagnosticExport('json')">↓ ${t('导出诊断报告','Export diagnosis')}</button>${diagBackend()?`<button onclick="diagnosticImport()">＋ ${t('导入证据包','Import evidence')}</button><button class="primary" onclick="diagnosticGenerateModal()">＋ ${t('从官网生成诊断','Diagnose a website')}</button>`:`<button class="primary" onclick="diagnosticImport()">＋ ${t('导入证据包','Import evidence')}</button>`}`;const note=document.querySelector('main > .notice');note.innerHTML=`<span>${b.demo?t('DEMO · 以下诊断为虚构示例；可导入自己的离线证据包，重新计算并导出。','DEMO · Synthetic diagnosis. Import your offline evidence bundle to recompute and export.'):b.generator?t('后台诊断 · '+b.run_manifest.brand+' · '+b.run_manifest.market+' · '+(b.run_manifest.mode==='full'?'含 AI 回答':'仅页面')+'；可在“历史诊断”中重新打开。','Backend diagnosis · reopen it from the history list.'):t('会话诊断 · 已载入你的证据包；数据仅在浏览器内存中处理，刷新前请导出。','Session diagnosis · Your evidence bundle is loaded. Data stays in browser memory; export before refreshing.')}</span>`;document.querySelector('header .actions > span').textContent=b.run_manifest.brand+' / '+title(page)};

/* Backend diagnosis: website -> fixed rule catalog -> v0.1 bundle stored by the runner (no model calls). */
let diagRuns={list:[],requested:false,timer:null,error:'',pending:null};
const diagBackend=()=>typeof geoRemoteMode==='function'&&(geoRemoteMode()||geoLocal());
const diagStatus={queued:['等待中','Queued'],running:['抓取与判定中','Running'],finished:['已完成','Finished'],failed:['失败','Failed'],interrupted:['已中断','Interrupted']};
async function diagnosticRefresh(){if(!diagBackend())return;clearTimeout(diagRuns.timer);try{const r=await geoFetch('diagnoses');diagRuns.list=Array.isArray(r.diagnoses)?r.diagnoses:[];diagRuns.error='';const done=diagRuns.list.find(x=>x.id===diagRuns.pending&&!['queued','running'].includes(x.status));if(done){diagRuns.pending=null;if(done.status==='finished'){toast(t('诊断完成','Diagnosis finished'));await diagnosticOpen(done.id);return}toast(t('诊断失败：','Diagnosis failed: ')+(done.failure||''))}if(diagRuns.list.some(x=>['queued','running'].includes(x.status)))diagRuns.timer=setTimeout(diagnosticRefresh,3000)}catch(e){diagRuns.error=e.message}if(page==='diagnostic')render()}
function diagnosticHistory(){if(!diagBackend())return '';if(!diagRuns.requested){diagRuns.requested=true;setTimeout(diagnosticRefresh)}const loaded=bundle?.run_manifest?.run_id;return `<section class="card table-card" style="margin-bottom:18px"><div class="card-head"><h2>${t('历史诊断','Diagnosis history')}</h2><button class="small" onclick="diagnosticRefresh()">${t('刷新','Refresh')}</button></div>${diagRuns.error?`<p class="error" role="alert">${esc(diagRuns.error)} ${geoRemoteMode()?`<a href="#/w/${ws}/research">${t('前往登录团队后台','Sign in to the team backend')} →</a>`:''}</p>`:''}${diagRuns.list.length?table([t('时间','Time'),t('品牌 / 市场','Brand / market'),t('官网','Website'),t('范围','Scope'),t('状态','Status'),''],diagRuns.list.map(x=>`<tr><td>${esc(new Date(x.created_at).toLocaleString())}</td><td><b>${esc(x.brand)}</b> · ${esc(x.market)}</td><td class="mono" style="overflow-wrap:anywhere">${esc(x.website)}</td><td>${x.mode==='full'?t('页面 + AI 回答','Pages + answers'):t('仅页面','Pages only')}</td><td>${esc(label(diagStatus,x.status))}${x.status==='finished'&&x.unknown?` <small class="muted">· ${x.unknown} ${t('条待补证据','unknown')}</small>`:''}${x.failure?`<div class="error small">${esc(x.failure)}</div>`:''}</td><td>${x.status==='finished'?`<div class="actions">${x.id===loaded?`<span class="tag">${t('当前','Open')}</span>`:`<button class="small" onclick="diagnosticOpen('${esc(x.id)}')">${t('打开','Open')}</button>`}${bundle&&x.id!==loaded?`<button class="small" onclick="diagnosticOpen('${esc(x.id)}',true)">${t('作为复测基线','Use as baseline')}</button>`:''}</div>`:''}</td></tr>`).join('')):`<p class="muted" style="padding:0 20px 16px">${diagRuns.requested&&!diagRuns.error?t('还没有后台诊断。点击“从官网生成诊断”开始。','No backend diagnoses yet.'):t('正在读取…','Loading…')}</p>`}</section>`}
async function diagnosticOpen(id,baseline=false){try{const j=await geoFetch('diagnosis?id='+encodeURIComponent(id));if(j.status!=='finished'||!j.bundle)throw Error(j.failure||t('诊断尚未完成','Diagnosis not finished'));const b=validateBundle(j.bundle);if(baseline)comparison=compareBundles(b,activeBundle());else{bundle=structuredClone(b);comparison=null}diagnosticTab=baseline?'retest':'summary';if(page!=='diagnostic')go('diagnostic');render()}catch(e){toast(e.message)}}
function diagnosticGenerateModal(){const d=(typeof geoDraft==='object'&&geoDraft[geoMarket])||{},runs=(geoState?.runs||[]).filter(r=>['finished','partial'].includes(r.status)),m=geoMarket==='US'?'US':'CN';modal(head(t('从官网生成诊断','Diagnose a website'))+`<form onsubmit="diagnosticGenerate(event)"><p class="subtitle">${t('后台抓取首页、最多 7 个代表页（关于、产品、FAQ、联系、文章等）以及 robots.txt 和站点地图，按固定规则逐条判定。不执行网页脚本、不调用模型、不产生模型费用；无法判定的规则保留为“证据不足”。','The backend fetches the homepage, up to 7 representative pages, robots.txt and the sitemap, then applies the fixed rules. No JavaScript, no model calls; undecidable rules stay unknown.')}</p>${input(t('官网地址','Website'),'dg-website',d.website||'')}${input(t('品牌名称','Brand name'),'dg-brand',String(d.brand||'').split(/[,，、]/)[0].trim())}<label for="dg-aliases">${t('别名（可选，逗号分隔，最多 10 个）','Aliases (optional, comma separated)')}</label><input id="dg-aliases" value="${esc(String(d.brand||'').split(/[,，、]/).slice(1).map(x=>x.trim()).filter(Boolean).join(', '))}"><label for="dg-market">${t('目标市场','Target market')}</label><select id="dg-market"><option value="CN" ${m==='CN'?'selected':''}>${t('中国','China')}</option><option value="US" ${m==='US'?'selected':''}>${t('美国','United States')}</option></select><label for="dg-flow">${t('关联品牌分析任务（可选，用于“AI 提及”和“AI 引用”两条规则）','Link a research run (optional, for the AI mention and citation rules)')}</label><select id="dg-flow"><option value="">${t('不关联 · 仅页面诊断','None · pages only')}</option>${runs.map(r=>`<option value="${esc(r.id)}" data-market="${esc(r.market)}">${esc(r.brand)} · ${esc(r.market)} · ${esc(new Date(r.created_at).toLocaleString())}${r.status==='partial'?' · '+t('部分完成','partial'):''}</option>`).join('')}</select>${submit(t('开始诊断','Start diagnosis'))}<p id="dg-error" class="error" role="alert"></p></form>`)}
async function diagnosticGenerate(e){e.preventDefault();const v=id=>$('#'+id).value.trim(),flow=$('#dg-flow').selectedOptions[0],body={website:v('dg-website'),brand:v('dg-brand'),market:v('dg-market'),aliases:v('dg-aliases').split(/[,，、]/).map(x=>x.trim()).filter(Boolean).slice(0,10)};if(flow?.value){if(flow.dataset.market!==body.market){$('#dg-error').textContent=t('所选分析任务的市场与诊断市场不一致。','The research run market does not match.');return}body.flow_id=flow.value}const button=e.target.querySelector('button[type=submit]');button.disabled=true;try{const j=await geoFetch('diagnose',body);diagRuns.pending=j.id;closeOverlay();toast(t('诊断已开始，通常需要 1–2 分钟','Diagnosis started; usually 1–2 minutes'));diagnosticRefresh()}catch(err){$('#dg-error').textContent=err.message;button.disabled=false}}
